const {chromium}=require('/Users/allanbranch/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const assert=require('node:assert/strict');
(async()=>{const b=await chromium.launch({channel:'chrome',headless:true});try{const p=await b.newPage();const errors=[];p.on('pageerror',e=>errors.push(e.message));for(const route of ['', 'public-safety-preview.html'])for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:900});await p.goto((process.env.PCARDS_TEST_URL||'http://localhost:4398/')+route);await p.locator('.expense-dashboard-card').first().waitFor();for(const mode of ['Department spending','Revenue & tax rates']){await p.getByRole('button',{name:mode,exact:true}).click();const picker=p.locator('#finance-add-comparison');assert.equal(await p.locator('.expense-dashboard-grid > .finance-add-card:last-child').count(),1);assert.equal(await p.locator('.finance-controls select').count(),0);if(mode==='Revenue & tax rates')assert.equal(await p.locator('.finance-card-title h3').first().innerText(),'Property taxes');const before=await p.locator('.expense-dashboard-card').count();const id=await picker.locator('option').nth(1).getAttribute('value');await picker.selectOption(id);await p.waitForTimeout(150);const card=p.locator('.expense-dashboard-card').last();assert.equal(await p.locator('.expense-dashboard-card').count(),before+1);assert.equal(await card.getAttribute('data-comparison-id'),id);assert(await card.locator('h3').first().evaluate(e=>e===document.activeElement));const box=await card.locator('h3').first().boundingBox();assert(box.y>=0&&box.y<900);assert.equal(await p.locator('.finance-card-title h3 a,.finance-card-title h3 button').count(),0);assert.equal(await card.locator('.finance-card-title h3').evaluate(e=>getComputedStyle(e).fontSize),'28px');assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await card.getByRole('button',{name:/^Remove/}).click();assert.equal(await p.locator('.expense-dashboard-card').count(),before);assert.equal(await picker.locator(`option[value="${id}"]`).count(),1);}console.log('PASS card titles, add/remove, focus, visibility, overflow',route||'home',width);}assert.deepEqual(errors,[]);}finally{await b.close();}})().catch(e=>{console.error(e);process.exit(1)});
